mapper.select:
SELECT  FROM places

ORDER BY updated_at DESC, place_id DESC
LIMIT #{size} OFFSET #{offset}

SELECT ,
       EXISTS (
           SELECT 1
           FROM favorites f
           WHERE f.user_id = #{userId,jdbcType=BIGINT}
             AND f.place_id = places.place_id
       ) AS favorite
FROM places

    is_active = TRUE


        AND is_recommended = TRUE


        AND (name ILIKE CONCAT('%', #{keyword}, '%')
            OR region ILIKE CONCAT('%', #{keyword}, '%')
            OR city ILIKE CONCAT('%', #{keyword}, '%'))


        AND category = #{category}


        AND region = #{region}


        AND EXISTS (
            SELECT 1
            FROM place_travel_styles pts
            WHERE pts.place_id = places.place_id
              AND pts.travel_style_id = #{styleId}
        )


ORDER BY favorite DESC, average_rating DESC, place_id DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE places SET is_recommended = #{recommended}, updated_at = CURRENT_TIMESTAMP(6)
WHERE place_id IN

    #{placeId}

UPDATE place_images
SET image_url = #{imageUrl}, alt_text = #{altText}
WHERE place_id = #{placeId} AND is_primary = TRUE
